"""About MALBA: reference-based company profile and academic director."""
import json
import build_academia as b
from build_consulting import defaults as consulting_defaults,contact,photo


def render_about(programs):
    data=json.loads((b.ROOT/'content/nosotros.json').read_text(encoding='utf-8'));d=data['director']
    hero=f'''<section class="about-hero consult-photo-section">{photo('assets/banner-transmision-1672.webp','assets/banner-transmision-960.webp','../',eager=True)}<div class="section-container about-hero-grid"><div><h1>{b.esc(data['title'])}</h1><p>{b.esc(data['description'])}</p><div class="consult-actions"><a class="button button-white" href="#enfoque">Conoce nuestro enfoque <span aria-hidden="true">↓</span></a><a class="consult-secondary" href="#consulta">Conversemos →</a></div></div><div class="about-hero-visual"><img src="../assets/hero/infraestructura-3d-1280.webp" srcset="../assets/hero/infraestructura-3d-640.webp 640w, ../assets/hero/infraestructura-3d-1280.webp 1280w" sizes="(max-width:760px) 200px, 440px" alt="Ilustración tridimensional de infraestructura de transmisión eléctrica" width="1280" height="1170" fetchpriority="high" decoding="async"></div></div></section>'''
    intro=f'''<section class="about-intro section-container" id="enfoque" aria-labelledby="about-intro-title"><div><h2 id="about-intro-title">{b.esc(data['introTitle'])}</h2>{''.join('<p>'+b.esc(p)+'</p>' for p in data['paragraphs'])}</div><figure class="about-principle">{b.picture('assets/programs/pmo-1672.webp','assets/programs/pmo-960.webp','Equipo de profesionales revisando información y planificación de un proyecto','../')}<figcaption><blockquote>«{b.esc(data['quote'])}»</blockquote><span>MALBA PMC</span></figcaption></figure></section>'''
    approach=f'''<section class="about-method consult-photo-section" aria-labelledby="about-method-title">{photo('assets/solutions/fondo-aprendizaje-digital-1672.webp','assets/solutions/fondo-aprendizaje-digital-960.webp','../')}<div class="section-container"><div class="about-heading"><h2 id="about-method-title">Un enfoque conectado con la realidad del proyecto.</h2><p>Conocimiento y práctica que se traducen en una forma de trabajar.</p></div><ol class="about-method-list">{''.join(f'<li><span aria-hidden="true">{i:02}</span><h3>{b.esc(x["title"])}</h3><p>{b.esc(x["description"])}</p></li>' for i,x in enumerate(data['approach'],1))}</ol></div></section>'''
    director=f'''<section class="about-director section-container" id="miguel-alba" aria-labelledby="director-title"><figure class="about-director-photo"><img src="../{b.esc(d['image'])}" alt="{b.esc(d['name'])}, director académico de MALBA PMC" width="264" height="396" loading="lazy" decoding="async"><figcaption>{b.esc(d['role'])}</figcaption></figure><div class="about-director-copy"><h2 id="director-title">{b.esc(d['name'])}</h2><p class="about-director-lead">{b.esc(d['description'])}</p>{''.join('<p>'+b.esc(p)+'</p>' for p in d['paragraphs'])}<dl class="about-credentials">{''.join('<div><dt>'+b.esc(x['title'])+'</dt><dd>'+b.esc(x['description'])+'</dd></div>' for x in d['credentials'])}</dl><a href="../consultoria/" class="about-text-link">Conoce cómo puede apoyar a tu organización <span aria-hidden="true">→</span></a></div></section>'''
    destinations=[('consultoria/','Consultoría','Acompañamiento en gestión de proyectos y riesgos.'),('academia/','Academia','Formación especializada y aprendizaje aplicado.'),('soluciones-digitales/','Soluciones digitales','Herramientas para entrenar y apoyar la toma de decisiones.')]
    ecosystem=f'''<section class="about-ecosystem section-container" aria-labelledby="about-ecosystem-title"><div class="about-heading"><h2 id="about-ecosystem-title">Una experiencia.<br>Tres formas de acompañarte.</h2><p>Encuentra la propuesta que responde a las necesidades de tu equipo.</p></div><div class="about-destinations">{''.join(f'<a href="../{url}"><h3>{title}</h3><p>{description}</p><span aria-hidden="true">→</span></a>' for url,title,description in destinations)}</div></section>'''
    contact_data=consulting_defaults();contact_data={**contact_data,'services':contact_data['services']+[{'id':'academy','name':'Academia y formación'},{'id':'digital','name':'Soluciones digitales'}]}
    contact_html=contact(contact_data).replace('data-consult-contact ','data-consult-contact data-contact-greeting="Hola, MALBA PMC. Quisiera información para mi organización." ').replace('el alcance de la consultoría.','la forma de acompañarte.').replace('Definimos un alcance a medida','Definimos una propuesta a medida')
    schema={'@context':'https://schema.org','@graph':[{'@type':'AboutPage','@id':b.ORIGIN+'quienes-somos/#page','name':'Nosotros · MALBA PMC','description':data['description'],'url':b.ORIGIN+'quienes-somos/','mainEntity':{'@id':b.ORIGIN+'#organization'}},{'@type':'Organization','@id':b.ORIGIN+'#organization','name':'MALBA PMC','url':b.ORIGIN,'logo':b.ORIGIN+'assets/malba-pmc-logo.png'},{'@type':'Person','@id':b.ORIGIN+'quienes-somos/#miguel-alba','name':d['name'],'jobTitle':d['role'],'image':b.ORIGIN+d['image'],'worksFor':{'@id':b.ORIGIN+'#organization'},'hasCredential':[{'@type':'EducationalOccupationalCredential','name':x['title']} for x in d['credentials']]},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Inicio','item':b.ORIGIN},{'@type':'ListItem','position':2,'name':'Nosotros','item':b.ORIGIN+'quienes-somos/'}]}]}
    main='<div class="about-page consult-page">'+hero+intro+approach+director+ecosystem+contact_html+'</div>'
    result=b.document('Nosotros',data['description'],'quienes-somos/','../',main,programs,'about',schema,'assets/banner-transmision-1672.webp','Infraestructura de transmisión eléctrica')
    return {'quienes-somos/index.html':result.replace('</head>','<link rel="stylesheet" href="../consultoria.css"><link rel="stylesheet" href="../nosotros.css"><script src="../consultoria.js" defer></script></head>')}
